<script setup>
import { computed, onBeforeUnmount, onMounted } from "vue";import CopyForAi from "./CopyForAi.vue";import {completeLesson,loadProgress,progressState,recordSection} from "../lib/progressStore.js";
const props=defineProps({lesson:Object,lessons:Array,base:String,sourceCommit:String});const published=computed(()=>props.lessons.filter(x=>x.status==='published'));const index=computed(()=>published.value.findIndex(x=>x.id===props.lesson.id));const previous=computed(()=>published.value[index.value-1]);const next=computed(()=>published.value[index.value+1]);const done=computed(()=>progressState.value?.completedLessons.includes(props.lesson.id));const url=p=>`${props.base.endsWith('/')?props.base:`${props.base}/`}${p.replace(/^\//,'')}`;let headings=[],frame;
function update(){cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{const passed=headings.filter(h=>h.getBoundingClientRect().top<=Math.min(180,innerHeight*.28));recordSection(props.lesson.id,passed.at(-1)?.id||'welcome')})}function complete(){completeLesson(props.lesson.id,props.lessons)}
onMounted(()=>{loadProgress();headings=[...document.querySelectorAll('.lesson-content h2[id],.lesson-content h3[id]')];addEventListener('scroll',update,{passive:true});addEventListener('hashchange',update);setTimeout(update,100)});onBeforeUnmount(()=>{removeEventListener('scroll',update);removeEventListener('hashchange',update);cancelAnimationFrame(frame)});
</script>
<template><nav class="lesson-progress" aria-label="Lesson navigation"><div class="lesson-crumbs"><a :href="url('')">Home</a><span>›</span><a :href="url('#roadmap')">{{lesson.module}}</a><span>›</span><strong>Lesson {{String(lesson.order).padStart(2,'0')}}</strong></div><div class="lesson-progress__actions"><a v-if="previous" :href="url(`/lessons/${previous.id}`)">← Previous</a><a :href="url('#roadmap')">Roadmap</a><button :disabled="done" @click="complete">{{done?'Completed ✓':'Mark lesson complete'}}</button><a v-if="next" :href="url(`/lessons/${next.id}`)">Next →</a><CopyForAi :lesson="lesson" :base="base" :source-commit="sourceCommit"/></div></nav></template>
